import React, { useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import '/styles/YearStartPage.css';

type YearStartPageProps = {
  /** URL видео для заднего фона */
  videoSrc?: string;
  /** Изображение-заглушка при отключённом видео */
  poster?: string;
};

export default function YearStartPage({
  videoSrc = './public/video.mp4',
  poster = './video-poster.jpg',
}: YearStartPageProps) {
  const videoRef = useRef<HTMLVideoElement | null>(null);

  useEffect(() => {
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReducedMotion && videoRef.current) {
      videoRef.current.pause();
      videoRef.current.removeAttribute('autoPlay');
      videoRef.current.loop = false;
    }
  }, []);

  return (

    <div className="year-hero-root">
  <video
  ref={videoRef}
  src="/video.mp4"
  autoPlay
  muted
  loop
  playsInline
  style={{ width: '100%', height: '100%', objectFit: 'cover' }}
/>

  {/* Полупрозрачный оверлей (чтобы текст был читаемым) */}
  <div className="year-hero-overlay" aria-hidden="true" />

  {/* Контент поверх видео */}
  <div className="year-hero-center">
    <div className="year-hero-card">
      <h1 className="year-hero-title">Расчет года исторического события</h1>
      <p className="year-hero-sub">
        Быстрое предсказание или расчет важного года по историческому событию.
      </p>
      <Link to="/persons" className="year-hero-button">
        Перейти к списку услуг
      </Link>
    </div>
  </div>
</div>
  );
}
